    @push('scripts')<script>async function updateTariff(event){event.preventDefault();const form=event.target;const body=Object.fromEntries(new FormData(form));const response=await fetch(form.action,{method:'PUT',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(body)});const json=await response.json();if(!response.ok){alert(json.message||Object.values(json.errors||{}).flat().join('\n')||'Perubahan gagal');return false;}alert(json.message);location.reload();return false;}</script>@endpush
